import{_t as e,it as t,n,rt as r}from"./chunks/framework.Ke88N3OB.js";var i=JSON.parse(`{"title":"Compatibility audit history","description":"","frontmatter":{"editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/tools/pumpkin-api/compatibility/history/README.md"},"headers":[],"relativePath":"tools/pumpkin-api/compatibility/history/README.md","filePath":"tools/pumpkin-api/compatibility/history/README.md","lastUpdated":1792252169000}`),a={name:`tools/pumpkin-api/compatibility/history/README.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="compatibility-audit-history" tabindex="-1">Compatibility audit history <a class="header-anchor" href="#compatibility-audit-history" aria-label="Permalink to “Compatibility audit history”">​</a></h1><p>Use these snapshots to see which API compatibility decisions were reviewed for a particular Pumpkin release and upstream WIT revision. The refresh command keeps the previous reviewed matrix when the WIT revision changes, so you can compare it with the new candidate without losing the audit for the earlier revision.</p><p>Each file is grouped by Pumpkin release and WIT package directory. Its name combines the upstream Git commit with the SHA-256 digest of the fetched WIT files:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&lt;pumpkin-release&gt;/&lt;wit-subdirectory&gt;/&lt;commit&gt;-&lt;wit-sha256&gt;.json</span></span></code></pre></div><p>The commit identifies the pinned source revision; the digest identifies the exact WIT content used for the audit. Both are part of the path so snapshots remain distinguishable if content differs. Snapshots are immutable: refresh writes a new snapshot and refuses to replace an existing one with different content. The active matrix is <code>../v0.1.1.json</code>; it can be updated while that Pumpkin release is current.</p><p>After changing <code>wit.lock.json</code>, run <code>pnpm --filter @pumpkin-plugins/static-hermes-runtime compatibility:refresh</code>. When the revision has changed, the command archives the previous matrix before writing the new candidate. It archives only a fully reviewed matrix, so resolve every pending compatibility decision and migration note before refreshing.</p>`,6)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};